$("#delete-account-form").addEventListener("submit", async (event) => {
  event.preventDefault();
  const button = $("#confirm-delete-account");
  button.disabled = true;
  $("#delete-account-error").textContent = "";
  try {
    const accounts = readAccounts();
    const storedAccount = accounts.find((entry) => entry.id === account?.id);
    const password = $("#delete-account-password").value;
    if (!storedAccount || (!storedAccount.cloudUid &&
        await hashPassword(password, storedAccount.passwordSalt) !== storedAccount.passwordHash)) {
      throw new Error(t("invalidCredentials"));
    }
    if (storedAccount.cloudUid) {
      await cloudRequest("/api/me", {
        method: "DELETE",
        body: { email: storedAccount.email, password }
      });
    }
    writeAccounts(accounts.filter((entry) => entry.id !== storedAccount.id));
    clearTimeout(cloudSyncTimer);
    clearCloudSession();
    localStorage.removeItem(STORAGE_KEYS.activeAccount);
    try {
      localStorage.removeItem(missionStorageKey);
      localStorage.removeItem(STORAGE_KEYS.missions);
    } catch (error) {
      showToast(`${t("localDataDeleteError")} ${error.message}`);
    }
    $("#delete-account-dialog").close();
    missionOwnerId = null;
    missionStorageKey = STORAGE_KEYS.missions;
    missionState = { cycle: 0, progress: {}, expiresAt: null };
    coins = 0;
    ownedSkins = new Set(Object.values(defaultSkins));
    selectedSkins = { ...defaultSkins };
    updateWallet();
    requireAuthentication();
    $("#auth-status").textContent = t("deleteAccountSuccess");
  } catch (error) {
    $("#delete-account-error").textContent = error.message || t("deleteAccountError");
  } finally {
    button.disabled = false;
  }
});
