async function prepareDebugPowerUp(type) {
  if ($("#screen-game").hidden || game.overlayMode === "over") await startGame();
  if (!game.running) return;
  game.powerUps.push({
    x: game.player.x,
    y: game.player.y - 8,
    type,
    speed: 0,
    ...(type === "pass-token" ? { tokenStyle: "snowflake" } : {})
  });
}

$("#test-shield").addEventListener("click", () => void prepareDebugPowerUp("shield"));
$("#test-triple").addEventListener("click", () => void prepareDebugPowerUp("triple"));
$("#test-pass-token").addEventListener("click", () => void prepareDebugPowerUp("pass-token"));
$("#test-game-over").addEventListener("click", async () => {
  if ($("#screen-game").hidden || game.overlayMode === "over") await startGame();
  else if (game.overlayMode === "paused") togglePause();
  if (!game.running) return;
  const plausibleDuration = 250 / ENEMY_SCORE * 0.42 + 0.25;
  if (game.elapsed < plausibleDuration) {
    await new Promise((resolve) => setTimeout(resolve, (plausibleDuration - game.elapsed) * 1000));
  }
  if (!game.running) return;
  game.score = 250;
  game.lives = 1;
  game.bullets = [];
  game.enemies = [{ x: game.player.x, y: game.player.y, speed: 0 }];
  renderScore(false);
  renderLives();
});
