document.addEventListener("keydown", (event) => {
  if (event.code === "KeyH" && game.running) {
    const target = event.target;
    if (target instanceof HTMLElement &&
        (target.isContentEditable || target.matches("input, textarea, select, [role='textbox']"))) return;
    event.preventDefault();
    useSpecialAbility();
    return;
  }
  if (event.code === "F3") {
    if (!account?.debugEnabled) return;
    event.preventDefault();
    $("#debug-toggle").click();
    return;
  }
  if (event.code === "Escape") {
    if (!$("#debug-panel").hidden) {
      $("#debug-close").click();
      return;
    }
    if (!$("#screen-game").hidden) togglePause();
  }
});

$("#special-ability-button").addEventListener("click", useSpecialAbility);

function movePlayerToPointer(event) {
  if (!game.running) return;
  const bounds = canvas.getBoundingClientRect();
  if (!bounds.width || !bounds.height) return;
  game.player.x = clamp((event.clientX - bounds.left) * canvas.width / bounds.width, 16, canvas.width - 16);
  game.player.y = clamp((event.clientY - bounds.top) * canvas.height / bounds.height, 18, canvas.height - 18);
}

canvas.addEventListener("pointermove", movePlayerToPointer);
canvas.addEventListener("pointerdown", (event) => {
  canvas.setPointerCapture(event.pointerId);
  movePlayerToPointer(event);
});

initialize();

if ("serviceWorker" in navigator && location.protocol !== "file:") {
  navigator.serviceWorker.register("./sw.js")
    .catch((error) => console.error("Não foi possível registrar o service worker do Neon Void.", error));
}
